module.exports=[7197,a=>{"use strict";let b=[{slug:"invoice-intake-automation",title:"Invoice intake automation for a wholesale distributor",kind:"demonstration",service:"ai",sector:"Distribution",summary:"How supplier invoices arriving by email could be read, checked against purchase orders and queued for approval, with a person confirming anything uncertain.",challenge:["A distributor receives supplier invoices as PDF attachments in a shared inbox. An accounts assistant opens each one, keys the details into the accounting system and compares the totals with the purchase order by eye.","The work is slow at month end, mismatches are found late, and nobody can easily see which invoices are waiting or why."],requirements:["Capture invoices from the shared inbox without changing how suppliers send them","Extract supplier, invoice number, dates, line items, tax and totals","Match each invoice to an open purchase order and flag differences","Keep a person responsible for approving every payment","Post approved invoices to the existing accounting system"],approach:[{title:"Read",body:"An intake service watches the inbox, stores each attachment and extracts structured fields using a document model, recording a confidence value for each field."},{title:"Check",body:"Deterministic rules compare the extracted data with purchase orders and supplier records. Arithmetic, tax and duplicate checks run on every invoice."},{title:"Review",body:"Invoices that pass go to an approval queue. Low-confidence fields and mismatches are highlighted beside the original document so the reviewer can correct them quickly."},{title:"Post",body:"Only approved invoices are written to the accounting system through its API, with a link back to the source document and the reviewer's decision."}],technologies:["Document extraction model","Workflow service","Review web application","Accounting system API","Relational database"],implementation:[{phase:"Discovery",body:"Sample a representative set of invoices, document the current steps and agree the matching rules."},{phase:"Pilot",body:"Run the pipeline alongside the manual process for a subset of suppliers and compare the results."},{phase:"Rollout",body:"Extend to remaining suppliers, train reviewers and add reporting on exceptions."}],measures:["Time from invoice receipt to approval","Share of invoices needing manual correction","Mismatches caught before payment"],results:[]},{slug:"field-service-operations-platform",title:"Operations platform for a field service company",kind:"demonstration",service:"software",sector:"Field services",summary:"A custom web application bringing job scheduling, technician updates and invoicing into one system in place of spreadsheets and phone calls.",challenge:["A service company schedules jobs on a shared spreadsheet. Technicians receive their day by message, report back by phone, and the office re-types job notes to raise invoices.","As the team grows the spreadsheet becomes fragile, jobs are occasionally double-booked and invoicing lags days behind completed work."],requirements:["A scheduling board the office can manage in real time","A mobile-friendly view for technicians, usable with poor signal","Job notes, photos and customer sign-off captured on site","Invoices generated from completed jobs","Role-based access for office staff, technicians and managers"],approach:[{title:"Model the work",body:"Customers, sites, jobs, visits and parts are defined as a data model first, so scheduling, reporting and invoicing all draw on the same records."},{title:"Design two interfaces",body:"A dense desktop board for dispatchers and a simple, large-target mobile view for technicians, each tested with the people who would use it."},{title:"Build in slices",body:"Scheduling first, then on-site capture, then invoicing, with each slice usable before the next begins."},{title:"Connect accounts",body:"Completed jobs produce draft invoices that sync to the accounting package after office review."}],technologies:["Web application framework","Progressive web app for mobile","REST API","Relational database","Accounting integration"],implementation:[{phase:"Design",body:"Prototype both interfaces and confirm the data model against real job histories."},{phase:"Build",body:"Deliver in two-week increments with demonstrations to office staff and technicians."},{phase:"Transition",body:"Import open jobs and customers, run both systems briefly, then retire the spreadsheet."}],measures:["Time between job completion and invoice","Scheduling conflicts per month","Calls between office and technicians"],results:[]},{slug:"crm-rollout-lead-routing",title:"CRM rollout and lead routing for a services firm",kind:"demonstration",service:"crm",sector:"Professional services",summary:"Consolidating enquiries from web, phone and referral into one CRM with automatic assignment and follow-up reminders.",challenge:["Enquiries reach a firm through a website form, a general email address, phone calls and partner referrals. Each partner keeps their own list, and follow-up depends on individual habit.","Leadership cannot see the pipeline as a whole, and some enquiries never receive a second contact."],requirements:["Capture every enquiry in one place regardless of channel","Assign leads by service line and availability","Prompt follow-ups and escalate when they are missed","Report on pipeline by source, stage and owner","Migrate existing contacts without duplicates"],approach:[{title:"Agree the pipeline",body:"Workshops define the stages, the meaning of each and the information required to move between them."},{title:"Configure and connect",body:"The CRM is configured to those stages, and the website form, shared inbox and phone system are connected so enquiries create records automatically."},{title:"Automate follow-up",body:"Assignment rules route each lead. Tasks and reminders are created on a schedule, with escalation to a manager if nothing happens."},{title:"Migrate and train",body:"Existing lists are cleaned, de-duplicated and imported. Short role-specific sessions get the team working in the system."}],technologies:["CRM platform","Website form integration","Email and telephony connectors","Reporting dashboards"],implementation:[{phase:"Process",body:"Define pipeline stages, ownership rules and reporting needs."},{phase:"Configuration",body:"Set up the CRM, integrations and automation in a test environment."},{phase:"Adoption",body:"Migrate data, train users and review usage after the first weeks."}],measures:["Time to first response on new enquiries","Share of leads with a scheduled next step","Pipeline value by source and stage"],results:[]},{slug:"multi-site-network-refresh",title:"Network refresh across three office locations",kind:"demonstration",service:"network",sector:"Multi-site business",summary:"Replacing an organically grown network with a documented, segmented and monitored design connecting a head office and two branches.",challenge:["A business has added offices over several years. Each has a different router, flat network and wireless setup, installed by whoever was available at the time.","Staff report slow file access between sites, guest devices share the same network as finance systems, and there is no monitoring to explain outages."],requirements:["Reliable, encrypted connectivity between all three sites","Separation of staff, guest, voice and server traffic","Consistent wireless coverage in each office","Central monitoring and alerting","Changeover outside working hours"],approach:[{title:"Survey",body:"Each site is audited: cabling, equipment, coverage and current configuration are recorded."},{title:"Design",body:"A standard design is produced for all sites, with addressing, segmentation, firewall policy and site-to-site VPN."},{title:"Stage and install",body:"Equipment is configured and tested in advance, then installed site by site during planned windows."},{title:"Monitor and document",body:"Monitoring is set up for links and devices, and the final build is documented for whoever maintains it."}],technologies:["Managed switching and routing","Site-to-site VPN","Business wireless","Firewall policy","Network monitoring"],implementation:[{phase:"Assessment",body:"Site surveys and a written report of findings and risks."},{phase:"Build",body:"Pre-staging, then one site per weekend with a rollback plan for each."},{phase:"Handover",body:"Diagrams, configuration backups and monitoring access handed to the client."}],measures:["Unplanned downtime per site","Inter-site transfer performance","Time to identify the cause of a fault"],results:[]}];a.s(["F",0,b,"j",0,function(a){return b.find(b=>b.slug===a)}])}];

